+async function readStock() {
+  const text = await readFile(STOCK_CSV, "utf8");
+  const [header, ...rows] = text.split(/\r?\n/).filter((line) => line.trim() !== "");
+  const keys = header.split(",");
+  return rows.map((line) => {
+    const cells = line.split(",");
+    const row = Object.fromEntries(keys.map((k, i) => [k, cells[i] ?? ""]));
+    return {
+      sku: row.sku,
+      name: row.name,
+      qty: Number(row.qty),
+      unit: row.unit === "" ? null : row.unit,
+      shelf: row.shelf,
+    };
+  });
+}

